<?php

if (! function_exists('card')) {
function card(
    string $slug,
    string $nameId,
    string $nameEn,
    string $category,
    string $hint,
    string $meaningId,
    string $meaningEn,
    string $etiquetteId,
    string $etiquetteEn,
    string $dressId,
    string $dressEn,
    string $banId,
    string $banEn,
    array $keys,
): array {
    $sections = fn (string $a, string $b, string $c, string $d) => [
        'sections' => [
            'meaning' => $a,
            'etiquette' => $b,
            'dress_code' => $c,
            'prohibitions' => $d,
        ],
        'citation_keys' => $keys,
    ];

    return [
        'slug' => $slug,
        'name_id' => $nameId,
        'name_en' => $nameEn,
        'category' => $category,
        'visual_hint' => $hint,
        'aliases' => [$nameId, $nameEn],
        'static_card_id' => $sections($meaningId, $etiquetteId, $dressId, $banId),
        'static_card_en' => $sections($meaningEn, $etiquetteEn, $dressEn, $banEn),
    ];
}
}

